import React, { useEffect, useMemo, useState } from 'react';
import { Button, Modal, Select } from '@linm-soft-org/linm-web-common-components';
import type { SelectOption } from '@linm-soft-org/linm-web-common-components';
import {
  canSelectVoucherApproveLevel,
} from '../../utils/voucherToolbarActions';
import { isFinalProcessingLevel } from '../../utils/voucherProcessingLevelDisplay';
import styles from '../../styles/documentForm.module.css';

export interface ProcessingLevelApproveModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentLevel: string;
  levelOptions: SelectOption[];
  onConfirm: (newLevel: string) => void | Promise<void>;
  saving?: boolean;
  testIdPrefix: string;
  /** List batch — nhiều phiếu mức khác nhau; Xác nhận luôn enable khi đã chọn mức. */
  batchMode?: boolean;
  /** Batch — số phiếu đã chọn (hiển thị gợi ý thay «mức hiện tại»). */
  selectedCount?: number;
  /** formPermissions.canApprove — mặc định true (batch / caller chưa truyền). */
  canApprove?: boolean;
  /** formPermissions.canUnpost ?? canApprove — hạ mức từ 9. */
  canUnpost?: boolean;
  /** Kỳ Locked — ẩn mức hạ từ 9. */
  periodLocked?: boolean;
}

/**
 * Phê duyệt — chọn mức xử lý mới (persist qua PUT khi chứng từ đã lưu).
 */
export const ProcessingLevelApproveModal: React.FC<ProcessingLevelApproveModalProps> = ({
  isOpen,
  onClose,
  currentLevel,
  levelOptions,
  onConfirm,
  saving = false,
  testIdPrefix,
  batchMode = false,
  selectedCount = 0,
  canApprove = true,
  canUnpost = true,
  periodLocked = false,
}) => {
  const [selected, setSelected] = useState(currentLevel);

  const visibleOptions = useMemo(() => {
    if (batchMode) return levelOptions;
    return levelOptions.filter(o =>
      canSelectVoucherApproveLevel({
        currentLevel,
        targetLevel: String(o.value ?? ''),
        canApprove,
        canUnpost,
        periodLocked,
      }),
    );
  }, [batchMode, levelOptions, currentLevel, canApprove, canUnpost, periodLocked]);

  useEffect(() => {
    if (!isOpen) return;
    if (batchMode) {
      setSelected(levelOptions[0]?.value?.toString() ?? currentLevel);
      return;
    }
    const currentVisible = visibleOptions.some(o => String(o.value) === String(currentLevel));
    setSelected(currentVisible ? currentLevel : String(visibleOptions[0]?.value ?? currentLevel));
  }, [isOpen, currentLevel, batchMode, levelOptions, visibleOptions]);

  const currentKey = String(currentLevel ?? '');
  const selectedKey = String(selected ?? '');
  const currentLabel =
    levelOptions.find(o => String(o.value) === currentKey)?.label ?? currentLevel;
  const selectedAllowed = batchMode
    || canSelectVoucherApproveLevel({
      currentLevel,
      targetLevel: selectedKey,
      canApprove,
      canUnpost,
      periodLocked,
    });
  const confirmDisabled = batchMode
    ? !selectedKey
    : !selectedKey || selectedKey === currentKey || !selectedAllowed;

  const atFinal = isFinalProcessingLevel(currentLevel);
  const hasOtherLevel = visibleOptions.some(o => String(o.value) !== currentKey);
  const emptyHint = !batchMode && !hasOtherLevel
    ? (periodLocked && atFinal
      ? 'Kỳ kế toán đã khóa sổ — không thể bỏ hoạch toán hoặc hạ mức xử lý'
      : atFinal && !canUnpost
        ? 'Không có quyền bỏ hoạch toán'
        : !canApprove
          ? 'Không có quyền phê duyệt mức xử lý'
          : undefined)
    : undefined;

  return (
    <Modal
      isOpen={isOpen}
      onClose={onClose}
      title="Phê duyệt — Mức xử lý"
      size="sm"
      data-testid={`${testIdPrefix}-approve-modal`}
    >
      {batchMode ? (
        <p style={{ marginBottom: 12, color: 'var(--color-text-secondary, #6b7280)', fontSize: 14 }}>
          Áp dụng mức xử lý cho{' '}
          <strong>{selectedCount > 0 ? `${selectedCount} phiếu đã chọn` : 'các phiếu đã chọn'}</strong>
          . Mỗi phiếu chỉ đổi mức khi đủ điều kiện nghiệp vụ.
        </p>
      ) : (
        <p style={{ marginBottom: 12, color: 'var(--color-text-secondary, #6b7280)', fontSize: 14 }}>
          Mức xử lý hiện tại: <strong>{currentLabel}</strong>
        </p>
      )}
      {emptyHint && (
        <p
          style={{ marginBottom: 12, color: 'var(--color-warning, #b45309)', fontSize: 13 }}
          data-testid={`${testIdPrefix}-approve-empty-hint`}
        >
          {emptyHint}
        </p>
      )}
      <div style={{ marginBottom: 16 }}>
        <label className={styles.label} htmlFor={`${testIdPrefix}-approve-level`}>
          Chuyển sang mức xử lý
        </label>
        <Select
          id={`${testIdPrefix}-approve-level`}
          data-testid={`${testIdPrefix}-approve-level`}
          options={visibleOptions}
          value={selected}
          onChange={(e: React.ChangeEvent<HTMLSelectElement>) => setSelected(e.target.value)}
        />
      </div>
      <div className={styles.modalActions}>
        <Button variant="secondary" onClick={onClose} data-testid={`${testIdPrefix}-approve-cancel`}>
          Hủy
        </Button>
        <Button
          variant="primary"
          onClick={() => onConfirm(selected)}
          loading={saving}
          disabled={confirmDisabled}
          data-testid={`${testIdPrefix}-approve-confirm`}
        >
          <i className="fas fa-check" /> Xác nhận
        </Button>
      </div>
    </Modal>
  );
};
